                                "event",
                                event,
                                "packet",
                                reached,
                                "offset",
                                headerOffset,
                                "level",
                                null,
                                "pn",
                                null,
                                "epoch",
                                null,
                                "status",
                                BAD_HEADER,
                                "sha256",
                                null));
                reached++;
                break;
